using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Research Agent – a .NET 10 console app that uses an AI agent to research a
// topic by searching the web, then summarise findings. The agent has access to
// two tools: WebSearch and NoteTaking.
// ---------------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool implementations ---------------------------------------------------

var researchNotes = new ResearchNotes();

IChatClient innerClient = new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient();

IChatClient agent = innerClient
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            return WebSearchSimulator.SearchAsync(query);
        },
        "web_search",
        "Search the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("A concise title for the note")] string title,
         [Description("The content of the note to save")] string content) =>
        {
            researchNotes.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Save a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = researchNotes.GetAll();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select((n, i) =>
                    $"[{i + 1}] {n.Title}\n{n.Content}"));
        },
        "read_notes",
        "Read all previously saved research notes."),
};

// --- Agent loop --------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent             ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));

var systemPrompt = $"""
    You are a research agent. Your job is to thoroughly research the topic the user
    provides by using the available tools.

    Follow this workflow:
    1. Use web_search to find information about the topic. Perform multiple searches
       with different queries to get comprehensive coverage.
    2. Use save_note to record key findings as you go – each note should capture a
       distinct insight, fact, or perspective.
    3. After gathering enough information (at least 3 searches), use read_notes to
       review everything you have collected.
    4. Finally, produce a well-structured summary of your research findings,
       citing the sources where appropriate.

    Be thorough but concise. Focus on accuracy and breadth of coverage.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic: {topic}"),
};

var options = new ChatOptions { Tools = [.. tools] };

Console.WriteLine();

var response = await agent.GetResponseAsync(messages, options);

Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('═', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('═', 50));

if (researchNotes.GetAll().Count > 0)
{
    Console.WriteLine();
    Console.WriteLine($"[{researchNotes.GetAll().Count} note(s) were saved during research]");
}

// ---------------------------------------------------------------------------
// Supporting types
// ---------------------------------------------------------------------------

/// <summary>Simple in-memory note store.</summary>
class ResearchNotes
{
    private readonly List<Note> _notes = [];

    public void Add(string title, string content) =>
        _notes.Add(new Note(title, content));

    public IReadOnlyList<Note> GetAll() => _notes;

    public record Note(string Title, string Content);
}

/// <summary>
/// Simulates web search results so the app works without an external search API.
/// Replace the body of SearchAsync with a real search API call (e.g. Bing Search)
/// for production use.
/// </summary>
static class WebSearchSimulator
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // Try a real lightweight search via DuckDuckGo Instant Answer API (no key needed).
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new StringBuilder();

            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.AppendLine($"Source: {abstractSource} ({abstractUrl})");
                results.AppendLine(abstractText);
                results.AppendLine();
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var t in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = t.TryGetProperty("Text", out var txtEl) ? txtEl.GetString() : null;
                    var firstUrl = t.TryGetProperty("FirstURL", out var urlEl) ? urlEl.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(firstUrl))
                            results.AppendLine($"  URL: {firstUrl}");
                        count++;
                    }
                }
            }

            if (results.Length > 0)
                return results.ToString();

            return $"Search for \"{query}\" returned limited results. Try a more specific query.";
        }
        catch
        {
            return $"Search for \"{query}\" returned limited results. Try a more specific query.";
        }
    }
}

